    {"id": "NJA-000031", "det": "DET-000057", "slug": "bits-job-lifecycle-correlation", "name_zh": "BITS 作业生命周期关联分析", "name_en": "BITS Job-Lifecycle Correlation Analytic", "refs": ["REF-000115"], "platforms": ["Windows"], "window_zh": "窗口至少覆盖三十日并跨系统重启保留作业身份，对达到策略最长寿命的环境延伸到九十日。", "window_en": "The window covers at least thirty days and retains job identity across system reboots, extending to ninety days where policy permits the default maximum lifetime.", "dimensions": ["device", "user", "bits_job", "remote_url", "callback", "process", "boot", "time"], "requirements": [("bits-job-audit", "BITS 作业与客户端事件", "BITS job and client events", ["timestamp", "device_id", "user_id", "job_id", "job_state", "remote_url", "notify_command"]), ("endpoint-process-lineage", "端点进程谱系", "Endpoint process lineage", ["timestamp", "device_id", "process_id", "parent_process_id", "image", "command_line", "user_id"]), ("network-connection", "网络连接事件", "Network connection events", ["timestamp", "device_id", "process_id", "destination", "protocol", "bytes_transferred"])], "observables": [("由异常主体创建且包含外部 URL 或通知命令的 BITS 作业", "A BITS job created by an unusual principal with an external URL or notification command"), ("BITS 服务传输后由系统服务谱系启动通知程序", "A notification program launched from system-service lineage after a BITS transfer")], "false_zh": "企业软件更新、消息同步和管理员恢复失败下载会形成长期 BITS 作业与回调。", "false_en": "Enterprise software updates, messaging synchronization, and administrator recovery of failed downloads can create long-lived BITS jobs and callbacks.", "blind_zh": "缺失 BITS-Client 事件、作业数据库被清理或回调发生在保留期之外会破坏关联。", "blind_en": "Missing BITS-Client events, deletion of the job database, or callback execution outside retention breaks correlation."},
    {"id": "NJA-000032", "det": "DET-000058", "slug": "management-plane-workload-execution", "name_zh": "管理面—工作负载执行关联分析", "name_en": "Management-Plane-to-Workload Execution Correlation Analytic", "refs": ["REF-000116", "REF-000118", "REF-000120"], "platforms": ["IaaS", "Containers", "ESXi"], "window_zh": "窗口从管理请求前十五分钟延伸到工作负载执行后一小时，并按代理队列或编排延迟调整。", "window_en": "The window starts fifteen minutes before the management request and extends one hour after workload execution, adjusted for agent queueing or orchestration delay.", "dimensions": ["principal", "request", "management_source", "workload", "agent", "process", "tenant", "cluster", "time"], "requirements": [("management-control-plane-audit", "云、容器与虚拟化管理审计", "Cloud, container, and virtualization management audit", ["timestamp", "principal_id", "source", "target_id", "action", "request_id", "result"]), ("workload-process-lineage", "来宾与容器进程谱系", "Guest and container process lineage", ["timestamp", "workload_id", "agent_process", "process_id", "parent_process_id", "image", "command_line"]), ("privileged-identity-context", "特权身份和变更情境", "Privileged identity and change context", ["timestamp", "principal_id", "role", "session_id", "approval_id", "maintenance_window", "source"] )], "observables": [("非常用主体或来源调用远程命令、容器 exec 或 Guest Operations 动作", "An uncommon principal or source invokes remote command, container exec, or Guest Operations actions"), ("管理请求后工作负载内由常驻代理派生异常命令或工具", "An unusual command or tool is spawned by a resident agent inside the workload after a management request")], "false_zh": "获准维护、自动修复、备份和事件响应会跨管理面批量执行命令。", "false_en": "Approved maintenance, automated remediation, backup, and incident response can execute commands in bulk through management planes.", "blind_zh": "控制面请求 ID 未进入工作负载、来宾或容器未采集进程以及跨租户日志不可用时会失去因果链。", "blind_en": "Causality is lost when control-plane request IDs do not reach workloads, guest or container process telemetry is absent, or cross-tenant logs are unavailable."},
    {"id": "NJA-000033", "det": "DET-000058", "slug": "container-creation-first-action", "name_zh": "容器创建—首个动作关联分析", "name_en": "Container Creation-to-First-Action Correlation Analytic", "refs": ["REF-000119"], "platforms": ["Containers"], "window_zh": "窗口覆盖创建请求前十分钟至容器启动后三十分钟，短命作业不得因终止而提前丢弃事件。", "window_en": "The window covers ten minutes before the creation request through thirty minutes after container start, and events for short-lived jobs are retained after termination.", "dimensions": ["principal", "request", "cluster", "namespace", "workload", "image_digest", "service_account", "node", "process", "network_destination", "time"], "requirements": [("container-admission-audit", "容器创建与准入审计", "Container creation and admission audit", ["timestamp", "principal_id", "request_id", "cluster_id", "namespace", "workload_id", "spec_hash", "admission_result"]), ("container-image-provenance", "镜像与发布谱系", "Image and release provenance", ["timestamp", "image_digest", "registry", "signature", "build_id", "release_id", "deployer_id"]), ("container-runtime-outcome", "容器运行时首个行为", "Container runtime first actions", ["timestamp", "workload_id", "container_id", "process", "command_line", "file_path", "network_destination", "privilege_flags"])], "observables": [("非发布主体创建规格近似但缺少可信发布谱系的新工作负载", "A non-release principal creates a specification-conforming workload without trusted release lineage"), ("常见基础镜像启动后立即取得载荷、开启外连或执行异常工具", "A common base image retrieves a payload, opens egress, or runs an unusual tool immediately after start")], "false_zh": "持续部署、自动扩缩、临时运维作业和开发测试会频繁创建短命容器。", "false_en": "Continuous delivery, autoscaling, temporary operations jobs, and development tests frequently create short-lived containers.", "blind_zh": "缺少不可变镜像摘要、准入请求主体或短命容器运行时遥测时，创建与真实内容无法可靠关联。", "blind_en": "Creation cannot be joined reliably to real content without immutable image digests, admission-request principals, or runtime telemetry for short-lived containers."},
