def prose(zh: str, en: str) -> dict[str, Any]:
    return {"paragraphs": [{"zh": zh.strip(), "en": en.strip()}]}


def lifecycle(status: str = "draft") -> dict[str, Any]:
    return {"status": status, "version": "1.0.0", "created": TODAY, "modified": TODAY, "contributors": ["Niji Matrix Research"], "reviewers": []}


def save(relative: str, data: dict[str, Any]) -> None:
    path = ROOT / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(yaml.safe_dump(data, allow_unicode=True, sort_keys=False, width=180), encoding="utf-8")


def all_subjects(parent: dict[str, Any]) -> list[str]:
    return [parent["id"], *[child["id"] for child in parent["children"]]]


def subject_names() -> dict[str, dict[str, str]]:
    result: dict[str, dict[str, str]] = {}
    for parent in PARENTS:
        result[parent["id"]] = {"zh": parent["name_zh"], "en": parent["name_en"]}
        for child in parent["children"]:
            result[child["id"]] = {"zh": child["name_zh"], "en": child["name_en"]}
    return result


def mechanism(item: dict[str, str], ref: str) -> dict[str, Any]:
    effects = {
        "NM-BT": ("关键执行语义落在原有监控或关联逻辑之外，防守方虽可见局部结果却难以还原完整因果，因此形成行为透明效果。", "Critical execution semantics fall outside existing monitoring or correlation logic. Defenders may see local outcomes but struggle to recover full causality, producing a Behavioral Transparency effect."),
        "NM-FD": ("恶意活动与合法实体共享可见特征，单点规则难以准确区分，因而形成特征伪装效果。", "The malicious activity shares visible features with legitimate entities, weakening point classification and producing a Feature Disguise effect."),
        "NM-ST": ("相关事件被分散到不同时间窗口或启动周期，局部阈值和短期查询只能看到片段，因而形成时空释痕效果。", "Related events are distributed across observation windows or boot cycles, leaving local thresholds and short queries with fragments and producing a Spatiotemporal Trace Dilution effect."),
        "NM-DO": ("已取得的数据仍不能直接解释真实内容或意图，因而形成数据遮蔽效果。", "Captured data still does not directly reveal true content or intent, producing a Data Obscuration effect."),
    }
    effect_zh, effect_en = effects[item["ref"]]
    return {"mechanism_ref": item["ref"], "role": item["role"], "summary": {"zh": item["zh"], "en": item["en"]}, "analysis": prose(f"该行为设计使{item['trace_zh']}。{effect_zh}残余可观测线索仍包括控制请求、进程结果、完整性变化或跨层时间关系，扩大遥测范围可以削弱这种匿迹。", f"This behavior design means {item['trace_en']}. {effect_en} Residual observables still include control requests, process outcomes, integrity changes, or cross-layer timing, so broader telemetry can weaken the stealth effect."), "evidence_refs": [ref], "confidence": "medium"}


