        decision_text_zh = "保留" if parent["decision"] == "retain" else "适配"
        decision_text_en = "retention" if parent["decision"] == "retain" else "adaptation"
        save(f"claims/{parent['claim']}-{parent['attack'].lower()}-{parent['slug']}.yaml", {"schema_version": "1.0.0", "type": "claim", "id": parent["claim"], "claim_type": "technique-relevance", "statement_zh": f"{parent['attack_zh']}能够通过{parent['stealth_zh']}改变执行痕迹与防守观察，因此适合作为 TA0002 下的{decision_text_zh}匿迹技术。", "statement_en": f"{parent['attack_en']} can change execution traces and defender observation because {parent['stealth_en']}; this supports {decision_text_en} as a stealth technique under TA0002.", "subject_refs": [parent["id"]], "evidence_refs": [parent["ref"]], "evidence_mode": "strongly-inferred", "confidence": "medium", "status": "review"})
        for child in parent["children"]:
            save(f"claims/{child['claim']}-{child['slug']}.yaml", {"schema_version": "1.0.0", "type": "claim", "id": child["claim"], "claim_type": "subtechnique-existence", "statement_zh": f"{child['name_zh']}以攻击者有意{child['variable_zh']}为稳定区分变量，并造成独立的痕迹与防守观察差异。", "statement_en": f"{child['name_en']} has a stable distinguishing variable: the adversary deliberately adopts {child['variable_en']}. This creates a distinct trace and defender-observation difference.", "subject_refs": [child["id"]], "evidence_refs": [parent["ref"]], "evidence_mode": "strongly-inferred", "confidence": "medium", "status": "review"})


