def write_techniques(status: str) -> None:
    for parent in PARENTS:
        base = f"matrix/tactics/TA0002-execution/techniques/{parent['id']}-{parent['slug']}"
        save(f"{base}/technique.yaml", build_parent(parent, status))
        for child in parent["children"]:
            save(f"{base}/subtechniques/{child['id']}-{child['slug']}/subtechnique.yaml", build_child(parent, child, status))


def targets_for_det(det: str) -> list[str]:
    return [subject for parent in PARENTS if parent["det"] == det for subject in all_subjects(parent)]


def targets_for_mit(mit: str) -> list[str]:
    return [subject for parent in PARENTS if parent["mit"] == mit for subject in all_subjects(parent)]


